<?php
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
$root=dirname(__DIR__);$of=$root.'/orders.json';$pf=__DIR__.'/products_data.json';
function out($c,$d){http_response_code($c);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function os($f){$x=is_file($f)?json_decode((string)file_get_contents($f),true):[];return is_array($x)?$x:[];}
function saveos($f,$x){return file_put_contents($f,json_encode(array_values($x),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n",LOCK_EX)!==false;}
function disc($u){$h=0;for($i=0;$i<strlen($u);$i++)$h=(($h*31)+ord($u[$i]))&0xffffffff;return 5+($h%11);}
function product($f,$id){$d=json_decode((string)@file_get_contents($f),true);foreach(($d['categories']??[])as$c)foreach(($c['items']??[])as$p)if((string)($p['id']??'')===$id)return$p;return null;}
$b=json_decode((string)file_get_contents('php://input'),true);if(!is_array($b))$b=$_POST;$a=(string)($b['action']??$_GET['action']??'');
if($a==='track'&&$_SERVER['REQUEST_METHOD']==='GET'){$id=trim((string)($_GET['order_id']??''));$u=trim((string)($_GET['uid']??''));foreach(os($of)as$o)if(($o['order_id']??'')===$id&&hash_equals((string)($o['uid']??''),$u))out(200,['ok'=>true,'status'=>$o['status'],'product_name'=>$o['product_name'],'amount'=>$o['amount'],'updated_at'=>$o['updated_at']]);out(404,['ok'=>false,'message'=>'Order not found']);}
if($_SERVER['REQUEST_METHOD']!=='POST')out(405,['ok'=>false,'message'=>'POST required']);
if($a==='create'){$u=trim((string)($b['uid']??''));$n=trim((string)($b['nickname']??''));$pid=trim((string)($b['product_id']??''));if(!preg_match('/^\d{6,12}$/',$u)||$n===''||$pid==='')out(400,['ok'=>false,'message'=>'Invalid UID or product']);$p=product($pf,$pid);if(!$p||($p['inStock']??true)===false||(int)($p['stock']??0)<=0)out(404,['ok'=>false,'message'=>'Product unavailable']);$base=(float)($p['price']??0);$d=disc($u);$amt=round($base*(100-$d))/100;$id='FF'.date('ymd').strtoupper(bin2hex(random_bytes(4)));$all=os($of);$all[]=['order_id'=>$id,'uid'=>$u,'nickname'=>$n,'product_id'=>$pid,'product_name'=>$p['name']??$pid,'base_amount'=>$base,'discount_percent'=>$d,'discount_amount'=>round($base-$amt,2),'amount'=>$amt,'status'=>'awaiting_payment','utr'=>'','created_at'=>date('c'),'updated_at'=>date('c')];if(!saveos($of,$all))out(500,['ok'=>false,'message'=>'Could not save order. Check PHP write permissions']);out(200,['ok'=>true,'order_id'=>$id,'discount'=>$d,'amount'=>$amt]);}
if($a==='submit_utr'){$id=trim((string)($b['order_id']??''));$utr=trim((string)($b['utr']??''));if(!preg_match('/^FF\d{6}[A-F0-9]{8}$/',$id)||strlen($utr)<6||strlen($utr)>40)out(400,['ok'=>false,'message'=>'Invalid order ID or UTR']);$all=os($of);$found=false;foreach($all as&$o)if(($o['order_id']??'')===$id){if(($o['status']??'')==='paid')out(409,['ok'=>false,'message'=>'Already paid']);$o['utr']=$utr;$o['status']='payment_review';$o['updated_at']=date('c');$found=true;break;}unset($o);if(!$found)out(404,['ok'=>false,'message'=>'Order not found']);if(!saveos($of,$all))out(500,['ok'=>false,'message'=>'Could not save UTR']);out(200,['ok'=>true,'status'=>'payment_review']);}
out(400,['ok'=>false,'message'=>'Unknown action']);
?>